import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional, Tuple

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def compare_cloudwatch_metrics(
    namespace: str,
    metric_name: str,
    dimension_name: Optional[str] = None,
    resource_a_value: Optional[str] = None,
    resource_b_value: Optional[str] = None,
    start_time: Optional[datetime] = None,
    end_time: Optional[datetime] = None,
    period: int = 300,
    stat: str = "Average",
    unit: Optional[str] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Compare an Amazon CloudWatch metric for two dimension filters over the same time window.

    Returns a dictionary containing raw series, aggregate summaries, and deltas.
    """
    if not namespace:
        raise ValueError("namespace is required")
    if not metric_name:
        raise ValueError("metric_name is required")
    if not dimension_name:
        raise ValueError("dimension_name is required")
    if resource_a_value is None or resource_b_value is None:
        raise ValueError("resource_a_value and resource_b_value are required")

    if end_time is None:
        end_time = datetime.now(timezone.utc)
    if start_time is None:
        start_time = end_time - timedelta(hours=1)

    if start_time.tzinfo is None:
        start_time = start_time.replace(tzinfo=timezone.utc)
    if end_time.tzinfo is None:
        end_time = end_time.replace(tzinfo=timezone.utc)

    cw = boto3.client("cloudwatch", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"))

    def build_metric_data_query(query_id: str, dim_value: str) -> Dict[str, Any]:
        metric_stat: Dict[str, Any] = {
            "Metric": {
                "Namespace": namespace,
                "MetricName": metric_name,
                "Dimensions": [{"Name": dimension_name, "Value": dim_value}],
            },
            "Period": period,
            "Stat": stat,
        }
        if unit:
            metric_stat["Unit"] = unit

        return {
            "Id": query_id,
            "MetricStat": metric_stat,
            "ReturnData": True,
        }

    try:
        response = cw.get_metric_data(
            MetricDataQueries=[
                build_metric_data_query("m1", resource_a_value),
                build_metric_data_query("m2", resource_b_value),
            ],
            StartTime=start_time,
            EndTime=end_time,
            ScanBy="TimestampAscending",
            MaxDatapoints=10000,
        )
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Failed to query CloudWatch metrics: {e}") from e

    results = {item["Id"]: item for item in response.get("MetricDataResults", [])}

    def normalize_series(item: Optional[Dict[str, Any]]) -> List[Dict[str, Any]]:
        if not item:
            return []
        timestamps = item.get("Timestamps", [])
        values = item.get("Values", [])
        points = [
            {"timestamp": ts.isoformat(), "value": val}
            for ts, val in sorted(zip(timestamps, values), key=lambda x: x[0])
        ]
        return points

    series_a = normalize_series(results.get("m1"))
    series_b = normalize_series(results.get("m2"))

    def summarize(points: List[Dict[str, Any]]) -> Dict[str, Any]:
        vals = [p["value"] for p in points if p["value"] is not None]
        if not vals:
            return {
                "count": 0,
                "sum": None,
                "average": None,
                "min": None,
                "max": None,
                "first": None,
                "last": None,
            }
        return {
            "count": len(vals),
            "sum": float(sum(vals)),
            "average": float(sum(vals) / len(vals)),
            "min": float(min(vals)),
            "max": float(max(vals)),
            "first": float(vals[0]),
            "last": float(vals[-1]),
        }

    summary_a = summarize(series_a)
    summary_b = summarize(series_b)

    def delta(lhs: Optional[float], rhs: Optional[float]) -> Optional[float]:
        if lhs is None or rhs is None:
            return None
        return float(lhs - rhs)

    comparison = {
        "window": {"start_time": start_time.isoformat(), "end_time": end_time.isoformat(), "period": period, "stat": stat},
        "metric": {"namespace": namespace, "metric_name": metric_name, "dimension_name": dimension_name, "unit": unit},
        "resource_a": {"dimension_value": resource_a_value, "series": series_a, "summary": summary_a},
        "resource_b": {"dimension_value": resource_b_value, "series": series_b, "summary": summary_b},
        "delta": {
            "sum": delta(summary_a["sum"], summary_b["sum"]),
            "average": delta(summary_a["average"], summary_b["average"]),
            "min": delta(summary_a["min"], summary_b["min"]),
            "max": delta(summary_a["max"], summary_b["max"]),
            "last": delta(summary_a["last"], summary_b["last"]),
        },
    }

    return comparison
